  "schema": "hermes/gas-rule-corpus-schema/v1",
  "note": "Field specs the corpus validator interprets. Type tokens are defined by hermes.py; a token here that hermes.py does not implement is a validation failure, not a skipped check.",
  "corpus_schema": "hermes/gas-rule-corpus/v1",
  "header": {
    "required": {
      "schema": "text",
      "source": "source",
      "fork_order": "fork-list"
    },
    "optional": {}
  },
  "source": {
    "required": {
      "path": "text",
      "sha256": "digest",
      "compiler_target": "version",
      "baseline_evm": "fork"
    },
    "optional": {}
  },
  "records": {
    "references": {
      "id_pattern": "^REF-[0-9]{2}$",
      "required": {
        "id": "id",
        "title": "text",
        "kind": "text",
        "url": "url",
        "footnote_title": "text",
        "source_section": "text"
      },
      "optional": {}
    },
    "myths": {
      "id_pattern": "^MYTH-[0-9]{2}$",
      "required": {
        "id": "id",
        "claim": "text",
        "correction": "text",
        "references": "ref-id-list",
        "source_section": "text"
      },
      "optional": {}
    },
    "rules": {
      "id_pattern": "^(CMP|STO|TRN|MEM|CTL|EXT|DEP|YUL)-[0-9]{2}$",
      "required": {
        "id": "id",
        "title": "text",
        "kind": "enum:rule_kind",
        "category": "text",
        "priority": "enum:priority",
        "evidence_grade": "enum:evidence_grade",
        "automation": "enum:automation",
        "hermes_class": "hermes-class-or-none",
        "statement": "text",
        "obligations": "text-list",
        "references": "ref-id-list",
        "source_section": "text",
        "verified_on": "verified-on",
        "scope": "scope"
      },
      "optional": {},
      "notes": {
        "statement": "The rule's body as the source document states it, whitespace collapsed, footnote markers lifted into references. Transcribed, not written.",
        "obligations": "Requirements the statement itself makes. Every entry has to be an exact substring of this rule's statement, which is what keeps an obligation the rule's own words rather than a paraphrase. Empty when the statement requires nothing. Derived by a stated heuristic: a sentence of the statement carrying a requirement verb. The heuristic has one known false-positive class, a sentence using \"requires\" descriptively rather than as an instruction, as STO-03 does; the cost of one is an operator explaining a mechanism, which is the safe direction for a gate that asks for an answer.",
        "hermes_class": "Authored. One of the twelve classes the harness already knows, or null for a rule that constrains the run rather than changing source.",
        "scope": "Authored. The range and fork floor over which the mechanism holds, each with its reason. The source pins one compiler and one fork; a scope copied from that header would refuse correct candidates on every other configuration."
      }
    }
  },
  "verified_on": {
    "required": {
      "compiler": "version",
      "evm": "fork"
    },
    "optional": {}
  },
  "scope": {
    "required": {
      "compiler_min": "version",
      "compiler_max_exclusive": "version",
      "compiler_reason": "text",
      "evm_floor": "fork",
      "evm_reason": "text",
      "pipelines": "pipeline-list",
      "pipeline_reason": "text"
    },
    "optional": {}
  },
  "enums": {
    "rule_kind": [
      "technique",
      "measurement",
      "architecture",
      "release_gate"
    ],
    "priority": [
      "P0",
      "P1",
      "P2"
    ],
    "evidence_grade": [
      "A",
      "B",
      "C",
      "X"
    ],
    "automation": [
      "safe",
      "guarded",
      "never"
    ],
    "pipeline": [
      "legacy",
      "via-ir"
    ]
  }
}

{
  "_comment": "Structural formulae. Not string-matchable as vocabulary; caught by pattern. These survive every vocabulary ban, which is why a wordlist alone does not work.",
  "patterns": {
    "negation_correction": {
      "note": "The single most reliable machine-prose tell. Sets up a strawman to knock down. 'X isn't just Y, it's Z.'",
      "severity": "high",
      "regex": "\\b(?:is|are|was|were|isn't|aren't|wasn't|weren't|it's|this is|that's|they're)\\s*(?:n't\\s+|not\\s+)?(?:just|only|merely|simply)\\b[^.!?]{0,120}?[,;]\\s*(?:it'?s|they'?re|but|it is|rather|that's)\\b"
    },
    "not_x_but_y": {
      "note": "Bare form of the same move.",
      "severity": "high",
      "regex": "\\bnot\\s+(?:because|that)\\b[^.!?]{0,90}?\\bbut\\s+(?:because|that)\\b"
    },
    "less_x_than_y": {
      "note": "Comparative variant. 'Less a protocol than a promise.'",
      "severity": "medium",
      "regex": "\\bless\\s+(?:a|an|of a)\\b[^.!?]{0,60}?\\bthan\\s+(?:a|an|of a)\\b"
    },
    "it_is_not_that": {
      "note": "'It's not that X; it's that Y.'",
      "severity": "high",
      "regex": "\\bit'?s not that\\b[^.!?]{0,120}?\\bit'?s that\\b"
    },
    "whether_or": {
      "note": "False-choice scaffolding. Absorbed from slopbeth STRUCTURE_PATTERNS. Signal only: fires on genuine enumerations.",
      "severity": "low",
      "regex": "\\bwhether\\b[^.!?]{0,90}?\\bor\\b",
      "signal_only": true
    },
    "from_x_to_y_sweep": {
      "note": "Fake-range gesture. 'From governance to settlement.' Absorbed from slopbeth. Signal only: fires on genuine enumerations.",
      "severity": "medium",
      "regex": "\\bfrom\\s+\\w+(?:\\s+\\w+)?\\s+to\\s+\\w+(?:\\s+\\w+)?\\s*[,.]",
      "signal_only": true
    },
    "rule_of_three": {
      "note": "Tidy triad. One or two is prose; a habit of three is a formula. Signal only: fires on genuine enumerations.",
      "severity": "low",
      "regex": "\\b[\\w'-]+,\\s+[\\w'-]+,\\s+(?:and|or)\\s+[\\w'-]+\\b",
      "signal_only": true
    },
    "em_dash": {
      "note": "Per the author's own slopbeth rule. Use a comma, colon, semicolon, or bracket.",
      "severity": "high",
      "regex": "[\\u2014\\u2013]"
    },
    "bold_lead_bullet": {
      "note": "'**Thing**: explanation' bullet. Skill-checklist shape leaking into prose.",
      "severity": "medium",
      "regex": "^\\s*[-*+]\\s+\\*\\*[^*\\n]{2,60}\\*\\*\\s*[:\\u2014-]"
    },
    "title_case_heading": {
      "note": "Headings In Title Case Like This.",
      "severity": "medium",
      "regex": "^#{1,6}\\s+(?:[A-Z][a-z']+\\s+){2,}[A-Z][a-z']+\\s*$",
      "case_sensitive": true,
      "allow_exact": [
        "# Wildcat Labs Skills",
        "## The Promise Machine"
      ]
    },
    "unrequested_tldr": {
      "note": "Only permitted when the user asked for one.",
      "severity": "medium",
      "regex": "^\\s*(?:\\*\\*)?(?:TL;?DR|Summary|Key Points|Overview)(?:\\*\\*)?\\s*:?\\s*$"
    },
    "apology_theatre": {
      "note": "Absorbed from slopgent. Apology in place of a cause and a fix.",
      "severity": "high",
      "regex": "\\b(?:i (?:sincerely |do |must )?apologi[sz]e|my apologies|sorry (?:about|for) (?:the|that|any)|uh oh|oops)\\b"
    },
    "unearned_we": {
      "note": "Agent adopting the user's first person plural on work the agent did not do.",
      "severity": "low",
      "regex": "\\bwe (?:have )?(?:successfully|now) (?:built|shipped|fixed|resolved|completed|implemented)\\b"
    },
    "emoji": {
      "note": "No.",
      "severity": "high",
      "regex": "[\\u2705\\u274c\\u2728\\u26a0\\U0001f300-\\U0001faff]"
    }
  },
  "cadence": {
    "note": "Rhythm tells. Reported as signals, not defects: judgement required.",
    "repeated_opener_threshold": 2,
    "sentence_length_variance_floor": 25.0,
    "max_consecutive_similar_length": 4
  }
}

